    const value = resolve(node.path, context);
    if (node.kind === "if") {
      output += renderNodes(isTruthy(value) ? node.body : node.alternate, context);
      continue;
    }

    if (Array.isArray(value) && value.length > 0) {
      for (let index = 0; index < value.length; index += 1) {
        output += renderNodes(node.body, {
          root: context.root,
          current: value[index],
          index,
          hasCurrent: true,
        });
      }
    } else {
      output += renderNodes(node.alternate, context);
    }
  }

  return output;
}

/** Render a Mini Template string using values from data. */
export function render(template: string, data: unknown): string {
  const nodes = parse(template);
  return renderNodes(nodes, {
    root: data,
    current: data,
    index: undefined,
    hasCurrent: false,
  });
}

import { describe, expect, test } from "bun:test";
import { render, TemplateError } from "../src/engine";

describe("interpolation", () => {
  test("resolves nested paths and escapes HTML", () => {
    expect(render("Hello, {{user.name}}: {{value}}", {
      user: { name: "Ada" },
      value: `&<>"'`,
    })).toBe("Hello, Ada: &amp;&lt;&gt;&quot;&#39;");
  });

  test("supports raw values, missing values, and scalar primitives", () => {
    expect(render("{{{html}}}|{{missing}}|{{zero}}|{{no}}", {
      html: "<b>ok</b>", zero: 0, no: false,
    })).toBe("<b>ok</b>||0|false");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("line\n{{user}}", { user: { name: "Ada" } }))
      .toThrow('Cannot render "user" as scalar text (received object) at line 2, column 1');
  });
});

describe("blocks", () => {
  test("implements the specified truthiness rules", () => {
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    for (const value of ["0", 1, {}, [0]]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
    }
  });

  test("iterates arrays with local paths, root fallback, this, and index", () => {
    const template = "{{#each users}}[{{@index}} {{name}}/{{site}}:{{this.name}}]{{else}}none{{/each}}";
    expect(render(template, {
      site: "example.test",
      users: [{ name: "Ada" }, { name: "Grace" }],
    })).toBe("[0 Ada/example.test:Ada][1 Grace/example.test:Grace]");
    expect(render(template, { site: "example.test", users: [] })).toBe("none");
  });

  test("supports nested loops and nested conditionals", () => {
    const template = "{{#each rows}}{{@index}}:{{#each this}}{{@index}}={{this}};{{/each}}{{#if enabled}}Y{{else}}N{{/if}}|{{/each}}";
    expect(render(template, { rows: [["a", "b"], ["c"]], enabled: true }))
      .toBe("0:0=a;1=b;Y|1:0=c;Y|");
  });
});

describe("syntax and whitespace", () => {
  test("preserves whitespace and removes comments", () => {
    expect(render("  a\n{{! hidden }}\n b  ", {})).toBe("  a\n\n b  ");
  });

  test.each([
    ["{{#wat x}}", "Unknown or malformed block"],
    ["{{/if}}", "has no matching opener"],
    ["{{#if x}}{{/each}}", "Mismatched closing block"],
    ["{{#if x}}", "Unclosed if block"],
    ["{{else}}", "Unexpected else outside"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate else"],
  ])("rejects %s", (template, message) => {
    expect(() => render(template, {})).toThrow(message);
  });

  test("reports useful line and column information", () => {
    try {
      render("first\ntext {{else}}", {});
      throw new Error("expected render to throw");
    } catch (error) {
      expect(error).toBeInstanceOf(TemplateError);
      expect((error as TemplateError).line).toBe(2);
      expect((error as TemplateError).column).toBe(6);
    }
  });
});

