import { describe, expect, test } from "bun:test";

const projectRoot = new URL("..", import.meta.url).pathname;

function runCli(...args: string[]) {
  return Bun.spawnSync({
    cmd: [process.execPath, "run", "src/cli.ts", ...args],
    cwd: projectRoot,
    stdout: "pipe",
    stderr: "pipe",
  });
}

describe("CLI", () => {
  test("writes only rendered text to stdout", () => {
    const result = runCli("test/fixtures/greeting.template", "test/fixtures/data.json");
    expect(result.exitCode).toBe(0);
    expect(result.stdout.toString()).toBe("Hello, Ada &amp; Grace!\n");
    expect(result.stderr.toString()).toBe("");
  });

  test("reports errors on stderr and exits non-zero", () => {
    const result = runCli("test/fixtures/greeting.template");
    expect(result.exitCode).not.toBe(0);
    expect(result.stdout.toString()).toBe("");
    expect(result.stderr.toString()).toContain("Usage:");
  });
});
